import unittest
from envsyntax import parse_entry
class Entries(unittest.TestCase):
 def test_blank(self):self.assertIsNone(parse_entry("  \n"))
 def test_comment(self):self.assertIsNone(parse_entry(" # key=value"))
 def test_normal(self):self.assertEqual(parse_entry("  KEY = value  "),("KEY","value"))
 def test_first_equals(self):self.assertEqual(parse_entry("KEY=a=b=c"),("KEY","a=b=c"))
 def test_unicode_value(self):self.assertEqual(parse_entry("KEY=雪 café"),("KEY","雪 café"))
 def test_literals(self):self.assertEqual(parse_entry('KEY="$HOME"'),("KEY",'"$HOME"'))
 def test_bad_keys(self):
  for line in ["=x","9KEY=x","bad-key=x","雪=x","a b=x"]:
   with self.subTest(line=line),self.assertRaises(ValueError):parse_entry(line)
 def test_missing_equals(self):
  with self.assertRaises(ValueError):parse_entry("KEY value")

import unittest
from envconfig import load
class Loading(unittest.TestCase):
 def test_empty(self):self.assertEqual(load([]),{})
 def test_duplicates(self):self.assertEqual(load(["A=one","A=two"]),{"A":"two"})
 def test_one_pass(self):self.assertEqual(load(iter(["A=one","B=two"])),{"A":"one","B":"two"})
 def test_comments(self):self.assertEqual(load([""," # comment","A=one"]),{"A":"one"})
 def test_empty_value(self):self.assertEqual(load(["A= "]),{"A":""})
 def test_invalid(self):
  with self.assertRaises(ValueError):load(["A=one","invalid"])
 def test_no_expansion(self):self.assertEqual(load(["A=$HOME"]),{"A":"$HOME"})
 def test_mixed_records(self):self.assertEqual(load(["_A9 = 雪","B=a=b","_A9=café"]),{"_A9":"café","B":"a=b"})

import re

_KEY_PATTERN = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")

def parse_entry(line):
    stripped = line.strip()
    if not stripped or stripped.startswith("#"):
        return None
    if "=" not in stripped:
        raise ValueError("missing =")
    key, value = stripped.split("=", 1)
    key = key.strip()
    value = value.strip()
    if not key:
        raise ValueError("empty key")
    if not _KEY_PATTERN.fullmatch(key):
        raise ValueError("invalid key")
    return key, value

from envsyntax import parse_entry

def load(lines):
    config = {}
    for line in lines:
        entry = parse_entry(line)
        if entry is None:
            continue
        key, value = entry
        config[key] = value
    return config
